// step - 1 add bootstrap cdn in to index.html

// step -2 React-Bootstrap  
/*
React Bootstrap
The most popular front-end framework, rebuilt for React.
React-Bootstrap replaces the Bootstrap JavaScript. Each component has been built 
from scratch as a true React component, without unneeded dependencies lik

npm install react-bootstrap bootstrap 

import Button from 'react-bootstrap/Button';

*/



import React from 'react'
import Alert from 'react-bootstrap/Alert';
import Badge from 'react-bootstrap/Badge';

function Boostrap() {
    var colors = ['primary',
        'secondary',
        'success',
        'danger',
        'warning',
        'info',
        'light',
        'dark'];
    return (
        <div className='container mt-5'>

            <Alert key="primary" variant="primary">
                This is a primary alert—check it out!
            </Alert>

            {
                colors.map((value, index, arr) => {
                    return (
                        <Alert key={value} variant={value}>
                            This is a primary alert—check it out!
                        </Alert>
                    )
                })
            }

            <Badge bg="primary">Primary</Badge>
            <Badge bg="secondary">Secondary</Badge>
            <Badge bg="success">Success</Badge>
            <Badge bg="danger">Danger</Badge>
            <Badge bg="warning" text="dark">
                Warning
            </Badge>
            <Badge bg="info">Info</Badge>
            <Badge bg="light" text="dark">
                Light
            </Badge>
            <Badge bg="dark">Dark</Badge>
                
        </div>
    )
}

export default Boostrap
